<script setup>
import {reactive,ref,computed,watch,nextTick} from 'vue';import {router} from '@inertiajs/vue3';import StudySheet from './StudySheet.vue';
const props=defineProps({catalog:Object,filters:Object,path:{default:'/progress'},student:Number}),sheet=ref(null),loading=ref(false),period=ref('all');
const defaults={subject:'',topic:'',difficulty:'',mode:'',from:'',to:''},form=reactive({...defaults});
const topics=computed(()=>[...new Set(props.catalog.topics.filter(t=>!form.subject||t.subject===form.subject).map(t=>t.topic))]);
function hydrate(){Object.assign(form,defaults,props.filters);period.value=props.filters.period||(props.filters.from||props.filters.to?'custom':'all')}
function open(){hydrate();sheet.value.open()}
function dates(){if(period.value==='custom')return;form.from='';form.to='';if(period.value!=='all'){const parts=new Intl.DateTimeFormat('en',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=t=>parts.find(p=>p.type===t).value;const date=new Date(get('year')+'-'+get('month')+'-'+get('day')+'T12:00:00Z');form.to=date.toISOString().slice(0,10);date.setUTCDate(date.getUTCDate()-(Number(period.value)-1));form.from=date.toISOString().slice(0,10)}}
function apply(){dates();if(form.from&&form.to&&form.from>form.to)return;router.get(props.path,{...form,period:period.value,...(props.student?{student:props.student}:{})},{preserveState:true,preserveScroll:true,replace:true,onStart:()=>loading.value=true,onSuccess:async()=>{loading.value=false;await nextTick();sheet.value.close()},onFinish:()=>loading.value=false})}
watch(period,dates);
watch(()=>form.subject,()=>{if(!topics.value.includes(form.topic))form.topic=''});
function reset(){Object.assign(form,defaults);period.value='all'}
const chips=computed(()=>Object.entries(props.filters).filter(([k,v])=>v&&['subject','topic','difficulty','mode'].includes(k)).map(([,v])=>v));
const timeLabel=computed(()=>props.filters.period==='custom'?[(props.filters.from||'Any date'),(props.filters.to||'today')].join(' to '):props.filters.period&&props.filters.period!=='all'?(props.filters.period==='1'?'Today':'Last '+props.filters.period+' days'):'All time');
</script><template><div class="compact-filters"><button @click="open">Filters <span v-if="chips.length">({{chips.length}})</span></button><span>{{[...chips,timeLabel].join(' · ')}}</span></div><StudySheet ref="sheet" title="Progress filters" :busy="loading"><div class="form-grid"><label>Subject<select v-model="form.subject"><option value="">All subjects</option><option v-for="s in catalog.subjects" :key="s">{{s}}</option></select></label><label>Time period<select v-model="period"><option value="all">All time</option><option value="1">Today</option><option value="7">Last 7 days</option><option value="30">Last 30 days</option><option value="custom">Custom dates</option></select></label><label>Topic<select v-model="form.topic"><option value="">All topics</option><option v-for="t in topics" :key="t">{{t}}</option></select></label><label>Difficulty<select v-model="form.difficulty"><option value="">All difficulties</option><option>Easy</option><option>Average</option><option>Difficult</option></select></label><label>Study tool<select v-model="form.mode"><option value="">All study tools</option><option value="fresh">Fresh Catch</option><option value="memory">Memory Maki</option><option value="tutor">Maki Mentor</option><option value="exam">Wasabi Rush</option><option value="assigned">Assigned exams</option></select></label><template v-if="period==='custom'"><label>From<input type="date" v-model="form.from"></label><label>Through<input type="date" v-model="form.to" :min="form.from"></label></template></div><p v-if="form.from&&form.to&&form.from>form.to" class="error" role="alert">End date must follow the start date.</p><template #actions><button :disabled="loading" @click="reset">Reset</button><button class="primary" :disabled="loading||!!(form.from&&form.to&&form.from>form.to)" @click="apply">{{loading?'Applying…':'Apply filters'}}</button></template></StudySheet></template>
